CREATE TABLE projects(id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(length(name)>0), created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))) STRICT;
CREATE TABLE sources(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN('video','image')), name TEXT NOT NULL, path TEXT NOT NULL, UNIQUE(project_id,path)) STRICT;
CREATE TABLE source_revisions(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE CASCADE, sha256 TEXT, bytes INTEGER NOT NULL, modified_ns TEXT NOT NULL, metadata_json TEXT, UNIQUE(source_id,sha256)) STRICT;
CREATE TABLE video_streams(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES source_revisions(id) ON DELETE CASCADE, stream_index INTEGER NOT NULL, codec TEXT NOT NULL, width INTEGER NOT NULL CHECK(width>0), height INTEGER NOT NULL CHECK(height>0), time_base_num INTEGER NOT NULL, time_base_den INTEGER NOT NULL CHECK(time_base_den>0), rotation INTEGER NOT NULL, sample_aspect_ratio TEXT NOT NULL, color_space TEXT NOT NULL, color_transfer TEXT NOT NULL, color_primaries TEXT NOT NULL, UNIQUE(revision_id,stream_index)) STRICT;
CREATE TABLE frame_indexes(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES source_revisions(id) ON DELETE CASCADE, video_stream_id TEXT REFERENCES video_streams(id), decoder_build TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('queued','indexing','ready','failed','cancelled')), error_json TEXT, frame_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))) STRICT;
CREATE TABLE frames(index_id TEXT NOT NULL REFERENCES frame_indexes(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL CHECK(ordinal>=0), pts_ticks TEXT, time_seconds REAL NOT NULL, duration_seconds REAL CHECK(duration_seconds IS NULL OR duration_seconds>0), timestamp_origin TEXT NOT NULL CHECK(timestamp_origin IN('source','best_effort','synthetic')), key_frame INTEGER NOT NULL CHECK(key_frame IN(0,1)), PRIMARY KEY(index_id,ordinal)) STRICT;
CREATE INDEX frames_timestamp ON frames(index_id,time_seconds,ordinal);
CREATE INDEX frames_pts ON frames(index_id,pts_ticks);
CREATE TABLE frame_selections(source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE CASCADE, index_id TEXT NOT NULL, ordinal INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(index_id,ordinal), FOREIGN KEY(index_id,ordinal) REFERENCES frames(index_id,ordinal) ON DELETE CASCADE) STRICT;
CREATE TABLE jobs(id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources(id) ON DELETE CASCADE, snapshot_json TEXT NOT NULL, status TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))) STRICT;
CREATE INDEX jobs_status ON jobs(status,updated_at);
CREATE TABLE export_jobs(job_id TEXT PRIMARY KEY REFERENCES jobs(id) ON DELETE CASCADE, destination TEXT NOT NULL, options_json TEXT NOT NULL) STRICT;
CREATE TABLE export_items(job_id TEXT NOT NULL REFERENCES export_jobs(job_id) ON DELETE CASCADE, index_id TEXT NOT NULL, ordinal INTEGER NOT NULL, image_path TEXT, checksum TEXT, status TEXT NOT NULL CHECK(status IN('pending','succeeded','failed')), PRIMARY KEY(job_id,index_id,ordinal), FOREIGN KEY(index_id,ordinal) REFERENCES frames(index_id,ordinal)) STRICT;
CREATE TABLE cache_records(key TEXT PRIMARY KEY, source_revision_id TEXT NOT NULL REFERENCES source_revisions(id) ON DELETE CASCADE, index_id TEXT REFERENCES frame_indexes(id) ON DELETE CASCADE, relative_path TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>=0), last_access TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), algorithm_version TEXT NOT NULL) STRICT;
CREATE INDEX cache_lru ON cache_records(last_access);
CREATE INDEX sources_project ON sources(project_id);
CREATE INDEX revisions_source ON source_revisions(source_id);
CREATE INDEX indexes_revision ON frame_indexes(revision_id);
